<?php use App\Core\Csrf; $base=$portal?'/portal/tickets':'/tickets'; $customer=$ticket['company_name']?:$ticket['contact_name']; $byReply=[];foreach($attachments as $attachment)$byReply[(int)$attachment['reply_id']][]=$attachment; ?>
<header class="page-header ticket-header"><div><a class="back-link" href="<?= $base ?>">← Support Tickets</a><div class="eyebrow"><?= htmlspecialchars((string)$ticket['ticket_number']) ?></div><h1><?= htmlspecialchars((string)$ticket['subject']) ?></h1><p><?= $portal?htmlspecialchars((string)$ticket['department_name']):htmlspecialchars((string)$customer).' · '.htmlspecialchars((string)$ticket['department_name']) ?></p></div><div class="header-actions"><span class="priority-badge <?= htmlspecialchars((string)$ticket['priority']) ?>"><?= htmlspecialchars(ucfirst((string)$ticket['priority'])) ?></span><span class="status <?= htmlspecialchars((string)$ticket['status']) ?>"><?= htmlspecialchars(ucwords(str_replace('_',' ',(string)$ticket['status']))) ?></span></div></header><?php if($flash): ?><div class="alert <?= htmlspecialchars($flash['type']) ?>"><?= htmlspecialchars($flash['message']) ?></div><?php endif; ?>
<div class="ticket-layout"><div class="ticket-conversation"><section class="thread"><?php foreach($replies as $reply): $staffReply=$reply['role']!=='customer'; ?><article class="reply <?= $staffReply?'staff-reply':'customer-reply' ?> <?= $reply['is_internal_note']?'internal-reply':'' ?>"><header><span class="reply-avatar"><?= htmlspecialchars(strtoupper(substr((string)$reply['name'],0,1))) ?></span><span><strong><?= htmlspecialchars((string)$reply['name']) ?></strong><small><?= $reply['is_internal_note']?'Private staff note':($staffReply?'Veelox Digital':'Customer') ?> · <?= date('j M Y, H:i',strtotime((string)$reply['created_at'])) ?></small></span></header><div class="reply-message"><?= nl2br(htmlspecialchars((string)$reply['message'])) ?></div><?php if(!empty($byReply[(int)$reply['id']])): ?><div class="attachment-list"><?php foreach($byReply[(int)$reply['id']] as $attachment): ?><a href="/ticket-attachments/<?= (int)$attachment['id'] ?>">↧ <?= htmlspecialchars((string)$attachment['original_name']) ?> <small><?= number_format($attachment['file_size']/1024,1) ?> KB</small></a><?php endforeach; ?></div><?php endif; ?></article><?php endforeach; ?></section>
<?php if($ticket['status']!=='closed'): ?><section class="reply-box"><div class="panel-heading"><div><span class="eyebrow">Conversation</span><h2>Add a reply</h2></div></div><form method="post" action="<?= $base.'/'.(int)$ticket['id'].'/reply' ?>" enctype="multipart/form-data"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><textarea name="message" rows="7" placeholder="Write your reply..." required></textarea><div class="reply-options"><label class="attachment-button">Attach file<input type="file" name="attachment" accept=".jpg,.jpeg,.png,.gif,.pdf,.txt,.zip"></label><?php if(!$portal): ?><label class="internal-toggle"><input type="checkbox" name="internal_note" value="1"> Private staff note</label><?php endif; ?><button class="primary-button">Send reply</button></div></form></section><?php else: ?><div class="closed-ticket">This ticket is closed. Staff can reopen it from the workflow panel.</div><?php endif; ?></div>
<aside class="ticket-sidebar"><?php if(!$portal): ?><section class="detail-card"><div class="panel-heading"><div><span class="eyebrow">Workflow</span><h2>Ticket settings</h2></div></div><form class="ticket-settings" method="post" action="/tickets/<?= (int)$ticket['id'] ?>/update"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><label>Status<select name="status"><?php foreach(['open','customer_reply','staff_reply','resolved','closed'] as $value): ?><option value="<?= $value ?>" <?= $ticket['status']===$value?'selected':'' ?>><?= htmlspecialchars(ucwords(str_replace('_',' ',$value))) ?></option><?php endforeach; ?></select></label><label>Priority<select name="priority"><?php foreach(['low','normal','high','urgent'] as $value): ?><option value="<?= $value ?>" <?= $ticket['priority']===$value?'selected':'' ?>><?= ucfirst($value) ?></option><?php endforeach; ?></select></label><label>Assigned to<select name="assigned_to"><option value="">Unassigned</option><?php foreach($staff as $member): ?><option value="<?= (int)$member['id'] ?>" <?= (int)$ticket['assigned_to']===(int)$member['id']?'selected':'' ?>><?= htmlspecialchars((string)$member['name']) ?></option><?php endforeach; ?></select></label><label>Department<select name="department_id"><?php foreach($departments as $department): ?><option value="<?= (int)$department['id'] ?>" <?= (int)$ticket['department_id']===(int)$department['id']?'selected':'' ?>><?= htmlspecialchars((string)$department['name']) ?></option><?php endforeach; ?></select></label><button class="primary-button full">Save settings</button></form></section><?php endif; ?><section class="detail-card"><div class="panel-heading"><div><span class="eyebrow">Details</span><h2>Ticket summary</h2></div></div><dl class="summary-list"><div><dt>Number</dt><dd><?= htmlspecialchars((string)$ticket['ticket_number']) ?></dd></div><div><dt>Department</dt><dd><?= htmlspecialchars((string)$ticket['department_name']) ?></dd></div><div><dt>Opened</dt><dd><?= date('j M Y',strtotime((string)$ticket['created_at'])) ?></dd></div><?php if(!$portal): ?><div><dt>Customer</dt><dd><a class="detail-link" href="/customers/<?= (int)$ticket['customer_id'] ?>"><?= htmlspecialchars((string)$customer) ?></a></dd></div><div><dt>Assigned</dt><dd><?= htmlspecialchars((string)($ticket['assignee_name']?:'Unassigned')) ?></dd></div><?php endif; ?></dl></section></aside></div>
